          [ "Aumentar a produção antes do gargalo sem elevar a vazão final tende a:", [ "Elevar estoque em processo", "Eliminar toda espera", "Reduzir automaticamente defeitos", "Aumentar a capacidade de entrega" ], "a", "A etapa limitante continua restringindo fluxo e o material pode se acumular." ],
          [ "O que deve acompanhar um indicador para torná-lo interpretável?", [ "Definição, unidade, período e origem do dado", "Apenas uma cor", "Um valor sem contexto", "Somente o nome do setor" ], "a", "Sem base e período, comparações podem ser enganosas." ],
          [ "Uma taxa de produção maior, mas com mais produto fora de especificação, significa:", [ "Que volume sozinho não demonstra melhoria", "Melhoria completa por definição", "Que qualidade não é relevante", "Que o dado de rejeição deve ser removido" ], "a", "Resultado deve integrar qualidade, segurança e necessidade do processo." ],
          [ "Como identificar um gargalo com mais confiabilidade?", [ "Observar fluxo, filas, capacidade efetiva e dados por etapa", "Escolher a máquina mais antiga", "Perguntar apenas a um cliente", "Comparar cores dos equipamentos" ], "a", "Medição do processo evidencia restrições reais e suas variações." ],
          [ "Por que comparar indicadores exige períodos e condições compatíveis?", [ "Para evitar atribuir diferenças a causas que não são comparáveis", "Porque unidades não importam", "Para esconder variação", "Porque um dado sempre vale para qualquer período" ], "a", "Demanda, mix de produto e condições alteram a interpretação." ],
          [ "Em um indicador de rendimento, qual cuidado é necessário?", [ "Definir claramente numerador e base de entrada", "Usar apenas produção total sem perdas", "Misturar unidades sem conversão", "Excluir produtos rejeitados sem explicar" ], "a", "A fórmula e a base devem refletir o objetivo de medição." ],
          [ "Qual é uma decisão responsável diante de dados incompletos?", [ "Sinalizar incerteza, validar fonte e evitar conclusões fortes", "Completar lacunas com números inventados", "Escolher o resultado mais favorável", "Apagar observações" ], "a", "Limitações do dado precisam ser transparentes antes de decidir." ],
          [ "Qual objetivo é compatível com gestão equilibrada?", [ "Melhorar fluxo e resultado mantendo requisitos de segurança e qualidade", "Maximizar produção a qualquer custo", "Aumentar estoques sem avaliar demanda", "Reduzir inspeção obrigatória" ], "a", "Desempenho sustentável considera requisitos técnicos, humanos e de cliente." ]
