          [ "O diagrama de causa e efeito serve principalmente para:", [ "Organizar hipóteses de possíveis causas", "Provar automaticamente qual causa é verdadeira", "Substituir coleta de dados", "Calcular custo de capital" ], "a", "A ferramenta estrutura investigação, mas hipóteses precisam de evidência." ],
          [ "Uma alteração reduz rejeição, mas aumenta risco de exposição química. O que fazer?", [ "Suspender ou reavaliar a mudança e tratar o risco antes de padronizar", "Padronizar porque qualidade melhorou", "Ocultar o efeito adverso", "Aumentar produção para compensar" ], "a", "Melhoria não deve transferir risco; segurança e ambiente são critérios de aceitação." ],
          [ "O que é estratificar dados?", [ "Separá-los por categorias relevantes para revelar padrões", "Misturar todos em uma média", "Excluir observações atípicas sem critério", "Converter todo dado em texto" ], "a", "Estratificação pode identificar grupos e condições associados ao problema." ],
          [ "Quando é apropriado padronizar uma mudança?", [ "Após verificar resultado e considerar riscos e repetibilidade", "Antes de qualquer teste", "Quando a hipótese parece convincente", "Somente para reduzir documentação" ], "a", "A padronização deve refletir uma solução comprovada e controlada." ],
          [ "Um resultado melhor aparece em apenas um turno. Qual passo é útil?", [ "Investigar diferenças de contexto e testar replicabilidade", "Generalizar para toda a planta sem análise", "Apagar os dados de outros turnos", "Concluir que o processo não varia" ], "a", "Condições distintas podem explicar o resultado; é preciso validar abrangência." ],
          [ "Por que a qualidade do sistema de medição importa numa melhoria?", [ "Erro ou viés de medição pode simular mudança", "Medições não influenciam conclusões", "Uma balança nunca deriva", "Apenas reduz o tempo de reunião" ], "a", "Dados inadequados podem levar a decisões equivocadas sobre desempenho." ],
          [ "Qual postura é adequada ao investigar falhas recorrentes?", [ "Focar o processo, evidências e condições contribuintes", "Atribuir culpa antes de verificar", "Alterar simultaneamente todas as variáveis", "Evitar registrar quase acidentes" ], "a", "Investigação sistêmica identifica barreiras e causas sem comprometer transparência." ],
          [ "Depois de uma ação eficaz, qual acompanhamento é importante?", [ "Monitorar indicadores e efeitos adversos ao longo do tempo", "Encerrar todos os registros", "Remover o responsável", "Parar de inspecionar" ], "a", "A verificação sustentada confirma que o ganho permanece e não cria novos problemas." ]
