      SeedCurriculum.module_data(
        "Viabilidade de negócio e decisão empreendedora",
        "Avalie proposta de valor, custos, riscos e premissas antes de comprometer recursos.",
        "Uma proposta empreendedora descreve para quem cria valor, qual problema resolve e como entrega e captura esse valor. Uma hipótese de mercado não é fato: precisa ser confrontada com entrevistas, dados, teste de protótipo ou pedidos verificáveis. A análise técnica avalia capacidade, qualidade, fornecimento, licenças e recursos; a financeira explicita investimento inicial, custos fixos e variáveis, preço, volume, capital de giro, fluxo de caixa e cenários.\n\nPonto de equilíbrio depende de custos fixos, preço e custo variável unitário, sob premissas simplificadas; não garante liquidez nem sucesso. Análises de sensibilidade mostram como alterações em demanda, preço, insumos e prazo afetam o resultado. Custos ambientais, segurança, tributos, manutenção e descarte não devem ser omitidos para tornar o projeto artificialmente atraente. Decisões devem indicar incertezas, limites de competência e critérios para interromper ou rever o investimento.",
        "Uma pequena produção estima custos fixos de R$ 12.000 por mês, preço de R$ 50 por unidade e custo variável de R$ 30. A margem de contribuição é R$ 20 por unidade; no modelo simplificado, seriam necessárias 600 unidades para cobrir custos fixos. Antes de investir, teste se existe demanda, se a capacidade e o capital de giro comportam esse volume e como o cenário muda se insumos subirem.",
        "No exemplo, qual é a margem de contribuição unitária?",
        [ "R$ 20", "R$ 30", "R$ 50", "R$ 600" ],
        "a",
        "Preço unitário menos custo variável unitário: R$ 50 − R$ 30 = R$ 20.",
        [
          [ "No modelo simples, o ponto de equilíbrio em unidades é calculado por:", [ "Custos fixos divididos pela margem de contribuição unitária", "Preço dividido por custos fixos", "Custos variáveis multiplicados pelo estoque", "Receita total somada ao investimento" ], "a", "A margem de contribuição de cada unidade cobre parte dos custos fixos." ],
          [ "Uma entrevista com cinco potenciais clientes comprova demanda em escala?", [ "Não; é evidência inicial que precisa ser ampliada e triangulada", "Sim, comprova vendas futuras", "Sim, elimina risco financeiro", "Não, entrevistas nunca fornecem informação" ], "a", "Entrevistas ajudam a testar hipóteses, mas não garantem comportamento de mercado." ],
          [ "Qual item pode ser custo variável?", [ "Matéria-prima consumida por unidade", "Aluguel fixo mensal no horizonte analisado", "Licença anual sempre fixa", "Depreciação tratada como fixa no modelo" ], "a", "O custo da matéria-prima tende a variar com o volume produzido." ],
          [ "Por que analisar capital de giro?", [ "Para avaliar recursos necessários entre pagamentos e recebimentos", "Para medir a cor da marca", "Para substituir toda previsão de venda", "Porque lucro e caixa são sempre iguais" ], "a", "Uma operação lucrativa pode enfrentar falta de caixa por descompasso temporal." ],
          [ "O que mostra uma análise de sensibilidade?", [ "Como o resultado muda quando uma premissa varia", "Que a projeção é certa", "Somente o preço final", "A identidade de todos os clientes" ], "a", "Ela explicita a exposição do resultado a variações de premissas relevantes." ],
          [ "Qual prática evita superestimar a viabilidade?", [ "Separar dados verificados de hipóteses e testar cenários", "Usar apenas o cenário otimista", "Excluir manutenção e conformidade", "Assumir capacidade máxima constante" ], "a", "Transparência sobre premissas e cenários reduz falsa precisão." ],
          [ "O custo de segurança e descarte deve ser:", [ "Incluído quando pertinente na avaliação do ciclo de vida", "Excluído por não gerar receita", "Adicionado somente após iniciar a operação", "Ignorado se o negócio for pequeno" ], "a", "Responsabilidades e custos de conformidade fazem parte de uma avaliação realista." ],
          [ "Se o custo dos insumos cresce, mas o preço não muda, o que pode ocorrer?", [ "A margem de contribuição pode cair", "A margem sempre aumenta", "O ponto de equilíbrio desaparece", "O custo fixo vira zero" ], "a", "Custos variáveis maiores reduzem a contribuição unitária, elevando o volume necessário para equilíbrio." ],
          [ "Quando é responsável interromper ou revisar um projeto?", [ "Quando critérios de risco, demanda ou viabilidade definidos não são atendidos", "Somente depois de gastar todo o orçamento", "Nunca, porque já houve investimento", "Quando surgem dados desfavoráveis" ], "a", "Critérios prévios de decisão permitem limitar perdas e tratar novas evidências com responsabilidade." ]
