    "seguranca-trabalho-meio-ambiente" => [
      SeedCurriculum.module_data(
        "Identificação de perigos e avaliação de riscos",
        "Separe perigo de risco e priorize controles pela eficácia, não pela conveniência.",
        "Perigo é uma fonte ou situação com potencial de causar dano; risco combina probabilidade e severidade em um contexto de exposição. A avaliação começa identificando tarefas, pessoas expostas, energias e condições anormais, incluindo limpeza, manutenção, partida e emergência. Uma matriz pode ajudar a priorizar, mas suas categorias são aproximações e não substituem requisitos legais, medições ou julgamento técnico competente.\n\nA hierarquia de controles prioriza eliminação, substituição e controles de engenharia antes de medidas administrativas e equipamentos de proteção individual. EPI é importante, mas depende de seleção, ajuste, treinamento e manutenção e não elimina o perigo. Controles devem ser verificados no campo e revistos após mudança, incidente, quase acidente ou nova informação. Relatar riscos sem retaliação e interromper atividade diante de perigo grave e iminente, conforme procedimentos e legislação aplicável, é parte da responsabilidade profissional.",
        "Ao transferir solvente volátil, identifique inflamabilidade e exposição por inalação. Primeiro avalie se o solvente ou etapa pode ser eliminado ou substituído; em seguida, considere sistema fechado, ventilação projetada e controle de fontes de ignição. Procedimentos e EPI complementam esses controles. A escolha final depende da ficha de segurança, avaliação local e normas aplicáveis.",
        "Na hierarquia de controles, qual medida geralmente vem antes do uso de EPI?",
        [ "Eliminar o perigo ou controlá-lo por engenharia", "Colocar um aviso e não avaliar", "Aumentar o tempo de exposição", "Reduzir o registro documental" ],
        "a",
        "Eliminação e controles de engenharia tendem a reduzir a exposição de modo mais robusto que depender apenas do comportamento individual.",
        [
          [ "Qual exemplo é um perigo?", [ "Vapor inflamável presente em uma área", "Probabilidade calculada sem fonte de dano", "Um formulário preenchido", "Uma meta mensal" ], "a", "O vapor inflamável pode causar dano; o risco depende também da exposição e das condições." ],
          [ "Qual medida representa eliminação?", [ "Remover uma etapa perigosa do processo", "Entregar luvas sem avaliar", "Colocar uma placa sem controle adicional", "Reduzir a frequência de inspeção" ], "a", "Eliminação remove a fonte de perigo quando viável." ],
          [ "Por que uma matriz de risco não deve ser tratada como verdade exata?", [ "Categorias e estimativas têm incertezas e limitações", "Porque risco nunca pode ser analisado", "Porque todos os riscos são iguais", "Porque matrizes substituem medições" ], "a", "A matriz organiza prioridades, mas precisa de contexto, dados e requisitos aplicáveis." ],
          [ "Um EPI foi especificado, mas não serve ao trabalhador. Qual é o problema?", [ "A proteção pode ser inadequada; ajuste e seleção precisam ser resolvidos", "A cor está incorreta somente", "Isso comprova que não existe perigo", "O procedimento se torna desnecessário" ], "a", "A eficácia do EPI depende de seleção correta, ajuste e compatibilidade com a tarefa." ],
          [ "Quando revisar uma avaliação de risco?", [ "Após mudanças, incidentes, quase acidentes ou nova informação", "Somente após cinco anos, sem exceção", "Nunca depois de aprovada", "Apenas quando muda o uniforme" ], "a", "Mudanças alteram perigos, exposições e eficácia dos controles." ],
          [ "Um alarme de gás dispara sem causa aparente. Qual resposta é adequada?", [ "Seguir procedimento de emergência e confirmar condição com segurança", "Desativar o detector imediatamente", "Entrar sem proteção para investigar", "Ignorar porque pode ser falha" ], "a", "A hipótese de falha do sensor não elimina a possibilidade de atmosfera perigosa." ],
          [ "Qual é a função de um controle de engenharia?", [ "Reduzir exposição por projeto ou barreira física/técnica", "Transferir toda responsabilidade ao operador", "Substituir manutenção", "Documentar apenas o treinamento" ], "a", "Ventilação, enclausuramento e proteções são exemplos que reduzem a exposição na fonte ou no caminho." ],
          [ "Por que registrar quase acidentes?", [ "Eles revelam falhas de barreiras antes de dano maior", "Para atribuir culpa automaticamente", "Porque substituem inspeção", "Para ocultar tendências" ], "a", "Aprender com eventos sem dano pode prevenir acidentes futuros." ],
          [ "Diante de risco grave e iminente, o profissional deve:", [ "Interromper e comunicar conforme procedimento e requisitos locais", "Prosseguir para cumprir a meta", "Remover barreiras de proteção", "Esperar que ocorra um acidente" ], "a", "A prioridade é proteger pessoas e controlar a situação segundo os procedimentos aplicáveis." ]
        ],
        level: "iniciante"
      ),
      SeedCurriculum.module_data(
        "Permissão de trabalho, isolamento e segurança de processo",
        "Planeje intervenções com controle de energias e verificação das condições reais de trabalho.",
        "Trabalhos não rotineiros podem envolver fontes elétricas, mecânicas, hidráulicas, pneumáticas, térmicas, químicas e energia armazenada. Um plano de isolamento identifica cada fonte, define dispositivo de bloqueio e etiquetagem, descarrega energias residuais e verifica condição segura antes do início. Fechar uma válvula ou desligar um painel não comprova isolamento: devem ser considerados vazamentos, retorno de fluxo, gravidade, capacitores, superfícies quentes e reenergização por terceiros.\n\nPermissões de trabalho e análises de tarefa coordenam escopo, equipe, atmosfera, ferramentas, barreiras e resposta a emergências; não são autorizações genéricas. Espaço confinado, trabalho a quente, altura e abertura de linha podem exigir controles especializados e equipes capacitadas. Se o escopo, as condições ou o turno mudarem, pare e revalide. Intertravamentos e dispositivos de segurança só podem ser alterados por processo formal autorizado, com medidas compensatórias e restauração verificada.",
        "Antes de abrir uma linha de processo, confirme identificação, conteúdo, isolamento de todas as fontes, drenagem e despressurização conforme procedimento, além de teste de ausência de energia ou condição perigosa quando aplicável. A equipe verifica os pontos de isolamento e coordena a permissão. Se o fluido ou a configuração não corresponder ao esperado, a tarefa não prossegue até a discrepância ser esclarecida.",
        "O que deve ser feito após aplicar bloqueio e etiquetagem?",
        [ "Verificar que as energias foram isoladas e controladas antes do trabalho", "Presumir que a etiqueta prova ausência de energia", "Remover o bloqueio para testar", "Permitir que qualquer pessoa reinicie o equipamento" ],
        "a",
        "A verificação confirma a condição de isolamento; bloqueio e etiqueta sem teste não bastam.",
        [
          [ "Por que energia armazenada deve ser considerada?", [ "Pode ser liberada e causar movimento ou exposição após desligamento", "Desaparece sempre ao desligar", "Só existe em motores", "É irrelevante em tubulações" ], "a", "Molas, pressão, calor e capacitores podem manter energia perigosa." ],
          [ "Uma permissão de trabalho deve estar vinculada a:", [ "Escopo, local, perigos, controles, equipe e validade definidos", "Uma autorização indefinida para qualquer tarefa", "Apenas nome do supervisor", "Somente o custo do serviço" ], "a", "A permissão deve controlar a atividade específica e as condições em que foi avaliada." ],
          [ "A equipe encontra uma linha diferente do desenho durante preparação. O que fazer?", [ "Parar, proteger a área e revalidar isolamento e documentação", "Prosseguir pelo trajeto mais curto", "Abrir a linha para descobrir o conteúdo", "Alterar a etiqueta" ], "a", "Divergência de campo invalida premissas do plano e exige nova avaliação." ],
          [ "Qual é uma exigência crítica para trabalho em espaço confinado?", [ "Avaliação atmosférica e plano de entrada e resgate adequados", "Apenas uma lanterna", "Entrar rapidamente sem comunicar", "Usar qualquer máscara disponível" ], "a", "Atmosfera e resgate requerem controles específicos e equipe capacitada." ],
          [ "Quando um intertravamento precisa ser inibido para serviço?", [ "Somente por processo formal autorizado, com controles e restauração verificada", "Quando atrasar a produção", "Por decisão unilateral do operador", "Sem registro, se for temporário" ], "a", "Inibição remove uma barreira e deve ser excepcional, autorizada e compensada." ],
          [ "Por que coordenar trabalhos simultâneos na mesma área?", [ "Uma atividade pode criar risco para outra equipe", "Para reduzir necessidade de comunicação", "Porque permissões não se sobrepõem", "Apenas para organizar horários" ], "a", "Interferências, fontes de ignição e isolamentos compartilhados precisam ser gerenciados." ],
          [ "O que fazer se condições meteorológicas invalidarem um trabalho em altura?", [ "Suspender e reavaliar conforme critérios do procedimento", "Manter a tarefa por causa do prazo", "Remover proteção contra queda", "Aumentar o número de pessoas na plataforma" ], "a", "Condições ambientais podem tornar controles inadequados e exigem interrupção segura." ],
          [ "No término do serviço, antes da reenergização, deve-se:", [ "Verificar pessoas, ferramentas, proteções e liberação formal dos bloqueios", "Retirar todos os bloqueios sem coordenação", "Ligar o equipamento com trabalhadores presentes", "Descartar a permissão sem revisão" ], "a", "Restauração segura exige confirmação da área e procedimento de retirada controlada." ],
          [ "Um detector indica atmosfera potencialmente perigosa. A resposta segura é:", [ "Interromper e seguir plano de evacuação e avaliação", "Continuar com proteção improvisada", "Desligar o detector", "Pedir que alguém entre para confirmar" ], "a", "A medição exige tratar a condição como perigosa até avaliação por equipe autorizada." ]
