          [ "Qual exemplo é mais verificável?", [ "Reduzir em 10% o consumo de água por lote sem exceder limite de qualidade", "Tornar o processo ótimo", "Usar uma solução bonita", "Melhorar bastante" ], "a", "Meta, base e restrição tornam o requisito avaliável." ],
          [ "O que é escopo do projeto?", [ "Limites do trabalho e entregas incluídas e excluídas", "Uma lista de desejos sem prioridade", "Apenas o orçamento", "O cronograma de outra equipe" ], "a", "Definir escopo evita ambiguidade sobre o que será entregue." ],
          [ "Uma tarefa depende da aprovação de um teste anterior. Como representar?", [ "Registrar dependência e sequência no plano", "Executá-la sem resultado do teste", "Excluir a aprovação", "Atribuir prazo aleatório" ], "a", "Dependências influenciam caminho de execução e previsão de prazo." ],
          [ "Para que serve um critério de aceite?", [ "Definir como verificar que uma entrega atende aos requisitos", "Garantir que todos gostem do projeto", "Substituir documentação", "Aumentar escopo automaticamente" ], "a", "Critérios de aceite permitem avaliação objetiva da entrega." ],
          [ "Uma restrição de segurança contradiz a solução inicial. O que deve ocorrer?", [ "Rever a solução e priorizar requisitos de segurança", "Ignorar a restrição", "Reduzir a meta sem comunicar", "Prosseguir e testar com pessoas expostas" ], "a", "A solução deve ser modificada ou interrompida para manter condições seguras." ],
          [ "Por que registrar premissas?", [ "Para revelar o que ainda precisa ser confirmado e avaliar impacto", "Para tratá-las como fatos", "Para impedir mudanças", "Para ocultar risco" ], "a", "Premissas explícitas podem ser verificadas e reavaliadas." ],
          [ "Qual uso é adequado para um protótipo inicial?", [ "Testar hipótese específica com investimento controlado", "Substituir validação final", "Liberar equipamento crítico sem análise", "Comprovar qualquer benefício" ], "a", "Protótipos reduzem incerteza, mas não equivalem a validação completa." ],
          [ "Ao mudar o escopo, a equipe deve:", [ "Avaliar impacto em prazo, custo, risco e requisitos e registrar aprovação", "Aceitar qualquer mudança sem avaliação", "Apagar o plano inicial", "Manter todas as entregas sem rever recursos" ], "a", "Controle de mudanças preserva coerência entre objetivo e recursos." ]
