          [ "Por que identificar versão de um desenho usado em teste?", [ "Para saber exatamente qual configuração gerou o resultado", "Para evitar leitura do desenho", "Porque toda versão é idêntica", "Apenas para organizar pastas" ], "a", "Configuração altera desempenho e deve estar associada às evidências." ],
          [ "Uma variável mudou entre testes. A comparação deve:", [ "Registrar a mudança e avaliar se ela afeta a conclusão", "Ignorar a diferença", "Combinar resultados como se fossem iguais", "Apagar um ensaio" ], "a", "Condições distintas podem confundir o efeito da variável investigada." ],
          [ "Um integrante identifica erro na montagem. Qual ação é correta?", [ "Comunicar, registrar e avaliar repetição segura do teste", "Omitir para não atrasar", "Alterar resultado manualmente", "Reiniciar sem investigar" ], "a", "A transparência permite decidir se os dados ainda são válidos." ],
          [ "Qual é o propósito de um registro de decisão?", [ "Documentar contexto, alternativas e justificativa", "Substituir evidência experimental", "Evitar prestação de contas", "Registrar apenas opiniões" ], "a", "Racional documentado facilita revisão e aprendizado da equipe." ],
          [ "Se houver pressão por prazo, mas controles de segurança não estiverem disponíveis:", [ "Suspender ou replanejar a tarefa", "Prosseguir com improviso", "Remover proteções", "Pedir ao integrante mais novo que execute" ], "a", "Prazo não justifica exposição a risco sem controle." ],
          [ "O que deve ocorrer com um procedimento revisado?", [ "Identificar versão vigente e retirar cópias obsoletas de uso", "Manter todas como igualmente válidas", "Alterar sem data", "Excluir a aprovação" ], "a", "Controle de versão evita executar instrução desatualizada." ],
          [ "Qual conduta é apropriada para dados inesperados?", [ "Investigar e preservar os dados antes de decidir sua validade", "Excluir automaticamente", "Forçar alinhamento com hipótese", "Ocultar da apresentação" ], "a", "Surpresas podem revelar falha, nova condição ou resultado relevante." ],
          [ "Antes de expandir um teste de bancada para escala maior, a equipe deve:", [ "Reavaliar riscos, escalonamento, limites e aprovações", "Assumir que escala não altera risco", "Usar o mesmo recipiente", "Dispensar monitoramento" ], "a", "Escala pode mudar transferência de calor, massa, energia e consequências de falha." ]
        ],
        level: "intermediario"
