      SeedCurriculum.module_data(
        "Validação, análise de resultados e transferência da solução",
        "Verifique requisitos com evidência e prepare uma entrega utilizável, segura e mantida.",
        "Validação pergunta se a solução atende à necessidade no contexto de uso; verificação confere se a entrega atende às especificações. Ambas exigem critérios definidos antes do teste, método adequado, instrumentos apropriados, amostra ou condição representativa e registro das limitações. Um resultado único não demonstra robustez quando há variação operacional. A análise deve comparar com linha de base e requisitos, considerar incerteza e investigar efeitos secundários.\n\nA entrega inclui documentação suficiente para operação, manutenção e decisão: configuração final, instruções aprovadas, riscos residuais, resultados, treinamento e plano de acompanhamento. Responsabilidade pela operação deve ser transferida a uma pessoa ou área competente, sem presumir que o protótipo esteja pronto para uso industrial. Recomendações devem separar evidência, inferência e proposta futura. Se a validação falha, a equipe comunica com clareza e propõe correção ou limites de uso, em vez de declarar sucesso por conveniência.",
        "Um protótipo de recuperação de calor reduz consumo em um ensaio controlado, mas ainda não foi exposto à variação de vazão e incrustação. A equipe declara o resultado observado, estima limites do ensaio e planeja validação adicional com critérios de parada e inspeção. A documentação não recomenda operação plena até que requisitos de segurança e desempenho sejam confirmados pelo responsável da instalação.",
        "Qual distinção entre verificação e validação é mais correta?",
        [ "Verificação confere requisitos especificados; validação confirma adequação ao uso pretendido", "São sinônimos sem diferença", "Validação é apenas revisão ortográfica", "Verificação avalia somente custo" ],
        "a",
        "A verificação compara entrega com especificações; a validação examina se a solução resolve a necessidade no contexto previsto.",
        [
          [ "Por que critérios de teste devem ser definidos antes de executar?", [ "Para reduzir interpretação oportunista dos resultados", "Para garantir resultado favorável", "Para permitir mudar limites depois", "Para dispensar plano de teste" ], "a", "Critérios prévios evitam ajustar a regra para favorecer a conclusão." ],
          [ "Um protótipo funciona em uma condição estável. O que isso prova?", [ "Desempenho naquela condição, não necessariamente em toda a faixa de uso", "Adequação universal", "Ausência de riscos", "Vida útil permanente" ], "a", "A evidência se limita às condições efetivamente testadas." ],
          [ "Uma solução atende desempenho, mas falha em manutenção segura. Qual conclusão é adequada?", [ "A validação está incompleta e a entrega não deve ser liberada sem tratar o requisito", "O projeto é sucesso completo", "Manutenção não é requisito", "A falha deve ser omitida" ], "a", "Adequação inclui segurança e manutenção quando fazem parte do uso pretendido." ],
          [ "O que caracteriza uma linha de base útil?", [ "Condição medida antes da intervenção com método e período definidos", "Uma lembrança sem dados", "O resultado final", "Uma meta sem valor observado" ], "a", "A comparação precisa de referência documentada e compatível." ],
          [ "Como comunicar resultado inconclusivo?", [ "Declarar evidência e incerteza e propor próximos passos", "Arredondar para sucesso", "Selecionar apenas um ensaio", "Evitar apresentação" ], "a", "A comunicação responsável deixa claro o alcance real e caminhos para reduzir incerteza." ],
          [ "Qual informação é essencial para transferência operacional?", [ "Configuração, procedimento aprovado, riscos e responsabilidades", "Somente o nome do projeto", "Uma foto sem instrução", "A lista de presença apenas" ], "a", "Operação segura requer documentação, treinamento e responsabilidades definidas." ],
          [ "O que fazer se a solução excede um limite de risco durante validação?", [ "Interromper, controlar a condição e revisar projeto e teste", "Aceitar porque o teste é temporário", "Aumentar limite após o fato", "Prosseguir sem informar" ], "a", "Limites de segurança continuam válidos durante testes e prototipagem." ],
          [ "Por que documentar riscos residuais?", [ "Para que usuários conheçam limitações e controles necessários", "Para provar que risco é zero", "Para evitar treinamento", "Para transferir toda responsabilidade ao operador" ], "a", "Riscos não eliminados precisam ser compreendidos e controlados." ],
          [ "Qual medida sustenta um benefício após entrega?", [ "Definir responsável, indicador e período de acompanhamento", "Encerrar coleta de dados imediatamente", "Remover procedimento", "Assumir que resultado se mantém" ], "a", "Monitoramento verifica sustentação e detecta deterioração ou efeitos inesperados." ]
